from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
import json
from typing import Any, Dict, List, Union

from pydantic import BaseModel, ValidationError, validator, root_validator


_TWO_PLACES = Decimal("0.01")


def _quantize_2(value: Decimal) -> Decimal:
    # Deterministic "banker's rounding" is not guaranteed across contexts;
    # explicitly round to 2 decimal places.
    return value.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)


def _ensure_utc(dt: datetime) -> datetime:
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def _format_issued_at(dt: datetime) -> str:
    # Required format: "YYYY-MM-DDTHH:MM:SSZ" in UTC
    dt_utc = _ensure_utc(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("sku")
    def _validate_sku(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("sku must be a non-empty string")
        return v

    @validator("quantity")
    def _validate_quantity(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def _parse_unit_price(cls, v: Any) -> Decimal:
        # Accept str/int/float; convert to Decimal safely.
        if isinstance(v, Decimal):
            dec = v
        elif isinstance(v, bool):
            # bool is int subclass; reject explicitly.
            raise ValueError("unit_price must be >= 0")
        elif isinstance(v, (int, str)):
            dec = Decimal(str(v).strip())
        elif isinstance(v, float):
            # Use string conversion to avoid some binary float artifacts.
            dec = Decimal(str(v))
        else:
            raise ValueError("unit_price must be a string, int, or float")

        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        return _quantize_2(dec)

    def unit_price_as_str(self) -> str:
        return f"{self.unit_price:.2f}"


class InvoiceExport(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]
    total: Decimal

    @validator("number")
    def _validate_number(cls, v: str) -> str:
        v = v.strip()
        if not v:
            raise ValueError("number must be a non-empty string")
        return v

    @validator("issued_at", pre=True)
    def _parse_issued_at(cls, v: Any) -> datetime:
        # Accept ISO 8601 string or datetime; naive values are UTC.
        if isinstance(v, datetime):
            return v
        if isinstance(v, str):
            s = v.strip()
            if not s:
                raise ValueError("issued_at must be a non-empty string")
            # Handle trailing 'Z'
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                # datetime.fromisoformat handles "+HH:MM" offsets.
                return datetime.fromisoformat(s)
            except ValueError as e:
                raise ValueError("issued_at must be a valid ISO 8601 datetime") from e
        raise ValueError("issued_at must be an ISO 8601 string or a datetime")

    @validator("lines")
    def _validate_lines(cls, v: List[InvoiceLine]) -> List[InvoiceLine]:
        if not isinstance(v, list) or len(v) == 0:
            raise ValueError("lines must be a non-empty list")
        return v

    @root_validator
    def _compute_total(cls, values: Dict[str, Any]) -> Dict[str, Any]:
        lines: List[InvoiceLine] = values.get("lines") or []
        total = Decimal("0.00")
        for line in lines:
            total += Decimal(line.quantity) * line.unit_price
        values["total"] = _quantize_2(total)
        return values

    def export_payload(self) -> Dict[str, Any]:
        return {
            "number": self.number,
            "issued_at": _format_issued_at(self.issued_at),
            "lines": [
                {"sku": line.sku, "quantity": line.quantity, "unit_price": line.unit_price_as_str()}
                for line in self.lines
            ],
            "total": f"{self.total:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate an invoice with Pydantic and return the billing API JSON text.

    Expected input:
      - number: str
      - issued_at: ISO 8601 string or datetime (naive => UTC)
      - lines: list of {sku: str, quantity: int>=1, unit_price: decimal>=0 as str/int/float}

    Output JSON object:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ" (UTC)
      - lines: [{sku, quantity, unit_price: "X.XX"}]
      - total: "X.XX" (sum of quantity * unit_price)
    """
    try:
        invoice = InvoiceExport.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError for invalid input (pydantic ValidationError is a ValueError subclass).
        raise ValueError(str(e)) from e

    payload = invoice.export_payload()
    return json.dumps(payload, separators=(",", ":"), ensure_ascii=False)

from __future__ import annotations

from typing import Any, Optional, List, Dict

from pydantic import BaseModel, ValidationError, validator


class ProfileImportModel(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name", pre=True)
    def _collapse_display_name_whitespace(cls, v: Any) -> str:
        if v is None:
            raise ValueError("display_name is required")
        if not isinstance(v, str):
            # Let pydantic handle type errors consistently, but provide clear message.
            raise TypeError("display_name must be a string")

        # Collapse internal whitespace to single spaces; trim leading/trailing.
        normalized = " ".join(v.split())
        if not normalized:
            raise ValueError("display_name must not be blank")
        return normalized

    @validator("bio", pre=True)
    def _normalize_bio(cls, v: Any) -> Optional[str]:
        if v is None:
            return None
        if not isinstance(v, str):
            raise TypeError("bio must be a string or null")
        # Treat empty/whitespace-only bio as None.
        normalized = v.strip()
        return normalized or None

    @validator("zip_code", pre=True)
    def _coerce_zip_code_to_str(cls, v: Any) -> str:
        if v is None:
            raise ValueError("zip_code is required")
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            normalized = v.strip()
            if not normalized:
                raise ValueError("zip_code must not be blank")
            return normalized
        # Let pydantic raise a validation error for other types.
        raise TypeError("zip_code must be a string or integer")


def import_profiles(rows: list) -> list:
    """
    Validate imported profile rows and return valid ones as dicts, in input order,
    silently skipping invalid rows.

    Each returned dict has:
      {"user_id": int, "display_name": str, "bio": str or None, "zip_code": str}
    """
    valid: List[Dict[str, Any]] = []
    for row in rows:
        try:
            model = ProfileImportModel.parse_obj(row)
            # Ensure the output shape is exactly as documented.
            valid.append(
                {
                    "user_id": model.user_id,
                    "display_name": model.display_name,
                    "bio": model.bio,
                    "zip_code": model.zip_code,
                }
            )
        except (ValidationError, ValueError, TypeError):
            # Silently skip invalid rows.
            continue
    return valid

import re
from typing import Any, Dict

from pydantic import BaseModel, EmailStr, ValidationError, validator


class _SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @validator("username")
    def _validate_username(cls, v: str) -> str:
        if v is None:
            raise ValueError("username is required")
        if not re.fullmatch(r"[a-z0-9_]{3,20}", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @validator("email", pre=True)
    def _normalize_email(cls, v: Any) -> str:
        if v is None:
            raise ValueError("email is required")
        s = str(v).strip().lower()
        # Requirement: must contain "@"
        if "@" not in s:
            raise ValueError('email must contain "@"')
        # Keep simple: return normalized string; no need for strict email parsing
        return s

    @validator("phone", pre=True)
    def _normalize_phone(cls, v: Any) -> str:
        if v is None:
            raise ValueError("phone is required")
        s = str(v)
        # Remove spaces, dots, dashes and parentheses
        s = re.sub(r"[ .\-\(\)]", "", s)
        # Must then be "+" followed by 8-15 digits
        if not re.fullmatch(r"\+\d{8,15}", s):
            raise ValueError("phone must be '+' followed by 8-15 digits")
        return s

    @validator("password")
    def _validate_password(cls, v: str) -> str:
        if v is None:
            raise ValueError("password is required")
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @validator("password_confirm")
    def _validate_password_confirm(cls, v: str, values: Dict[str, Any]) -> str:
        if v is None:
            raise ValueError("password_confirm is required")
        password = values.get("password")
        if password is None:
            # Let pydantic report missing/invalid password; keep consistent behavior
            raise ValueError("password must be provided before validating password_confirm")
        if v != password:
            raise ValueError("password_confirm must equal password")
        return v

    class Config:
        extra = "forbid"


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload using pydantic.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        pydantic.error_wrappers.ValidationError (subclass of ValueError)
        for any missing or invalid field.
    """
    try:
        model = _SignupModel.parse_obj(data)
    except ValidationError:
        # Requirement allows pydantic ValidationError; it's already a ValueError
        raise

    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, computed_field, field_serializer, field_validator


_TWO_PLACES = Decimal("0.01")
_ROUND = ROUND_HALF_UP


def _to_decimal_2(v: Any) -> Decimal:
    """
    Convert input (str/int/float/Decimal) to Decimal, then keep it unformatted.
    We intentionally quantize at serialization time.
    """
    if isinstance(v, Decimal):
        return v
    if isinstance(v, bool):
        # bool is an int subclass; reject explicitly
        raise ValueError("unit_price must be a number, not a boolean")
    if isinstance(v, (int, str)):
        return Decimal(str(v))
    if isinstance(v, float):
        # Avoid Decimal(float) binary artifacts by stringifying
        return Decimal(str(v))
    raise ValueError("unit_price must be a string, int, float, or Decimal")


def _quantize_2(d: Decimal) -> Decimal:
    return d.quantize(_TWO_PLACES, rounding=_ROUND)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(ge=1)
    unit_price: Decimal = Field(ge=0)

    @field_validator("unit_price", mode="before")
    @classmethod
    def _validate_unit_price(cls, v: Any) -> Decimal:
        try:
            return _to_decimal_2(v)
        except (InvalidOperation, ValueError) as e:
            raise ValueError("unit_price must be a non-negative decimal number") from e

    @field_serializer("unit_price")
    def _serialize_unit_price(self, v: Decimal) -> str:
        return format(_quantize_2(v), "f")


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    @field_validator("issued_at", mode="before")
    @classmethod
    def _parse_issued_at(cls, v: Any) -> datetime:
        # Let pydantic parse strings/datetimes where possible, then normalize.
        # - If naive -> treat as UTC
        # - If aware -> convert to UTC
        if isinstance(v, datetime):
            dt = v
        else:
            # Pydantic will handle ISO strings; but we still want consistent errors.
            # Use BaseModel parsing by creating a minimal datetime model via field parsing.
            # Easiest: just return v and let pydantic coerce; mode="before" requires a value.
            # We'll attempt to parse ISO strings ourselves for better control.
            if isinstance(v, str):
                # Support common ISO forms; rely on datetime.fromisoformat plus 'Z'.
                s = v.strip()
                if s.endswith("Z"):
                    # fromisoformat doesn't accept 'Z'
                    s = s[:-1] + "+00:00"
                try:
                    dt = datetime.fromisoformat(s)
                except ValueError as e:
                    raise ValueError("issued_at must be an ISO 8601 string or datetime") from e
            else:
                raise ValueError("issued_at must be an ISO 8601 string or datetime")

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    @field_serializer("issued_at")
    def _serialize_issued_at(self, v: datetime) -> str:
        # Always UTC with exact format: YYYY-MM-DDTHH:MM:SSZ
        v_utc = v.astimezone(timezone.utc)
        return v_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

    @computed_field
    @property
    def total(self) -> str:
        total = Decimal("0")
        for line in self.lines:
            total += _quantize_2(line.unit_price) * Decimal(line.quantity)
        return format(_quantize_2(total), "f")


def export_invoice(data: Dict[str, Any]) -> str:
    """
    Validate the invoice and return JSON text for the billing API.

    Raises:
        ValueError: for invalid input (via pydantic ValidationError, which is a ValueError).
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError:
        # Callers rely on ValueError being raised for invalid input.
        raise
    return invoice.model_dump_json()

from __future__ import annotations

from typing import Any, Optional, Union, List

from pydantic import BaseModel, ValidationError, field_validator


class ProfileImportRow(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @field_validator("display_name", mode="before")
    @classmethod
    def _normalize_display_name(cls, v: Any) -> Any:
        # Accept only strings for display_name; numeric types should fail validation.
        if v is None:
            return v
        if not isinstance(v, str):
            return v
        # Collapse internal whitespace to single spaces and trim ends.
        normalized = " ".join(v.split())
        return normalized

    @field_validator("display_name")
    @classmethod
    def _validate_display_name_non_blank(cls, v: str) -> str:
        if not v:
            raise ValueError("display_name must not be blank")
        return v

    @field_validator("zip_code", mode="before")
    @classmethod
    def _coerce_zip_code_to_str(cls, v: Any) -> Any:
        # zip_code may arrive as a string or an integer; keep as a string.
        if v is None:
            return v
        if isinstance(v, int):
            return str(v)
        if isinstance(v, str):
            return v
        return v


def import_profiles(rows: list) -> list:
    """
    Validate profile rows and return valid ones as dicts in input order,
    silently skipping invalid rows.

    Each returned dict has the shape:
      {"user_id": int, "display_name": str, "bio": str | None, "zip_code": str}
    """
    result: List[dict[str, Any]] = []
    for row in rows:
        try:
            model = ProfileImportRow.model_validate(row, from_attributes=False)
            result.append(model.model_dump())
        except ValidationError:
            # Silently skip invalid rows.
            continue
    return result

from __future__ import annotations

import re
from typing import Any

from pydantic import BaseModel, Field, ValidationError, field_validator


_USERNAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")
_EMAIL_HAS_AT = "@"
_PHONE_STRIP_RE = re.compile(r"[ .\-()]+")


class _SignupPayload(BaseModel):
    username: str = Field(..., description="Lowercase username matching ^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str
    password_confirm: str

    @field_validator("username")
    @classmethod
    def _validate_username(cls, v: str) -> str:
        if not _USERNAME_RE.match(v):
            raise ValueError("Invalid username format")
        return v

    @field_validator("email")
    @classmethod
    def _validate_email(cls, v: str) -> str:
        v = v.strip().lower()
        if _EMAIL_HAS_AT not in v:
            raise ValueError('Email must contain "@"')
        return v

    @field_validator("phone")
    @classmethod
    def _validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, and parentheses.
        compact = _PHONE_STRIP_RE.sub("", v)

        # Must be "+" followed by 8-15 digits
        if not re.fullmatch(r"\+[0-9]{8,15}", compact):
            raise ValueError("Invalid phone number format")
        return compact

    @field_validator("password")
    @classmethod
    def _validate_password(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("Password must be at least 8 characters")
        return v

    @field_validator("password_confirm")
    @classmethod
    def _validate_password_confirm(cls, v: str, info) -> str:
        # In Pydantic v2, info.data contains already-validated fields.
        data = getattr(info, "data", None) or {}
        password = data.get("password")
        if password is None or v != password:
            raise ValueError("password_confirm must match password")
        return v

    model_config = {
        "extra": "forbid",
    }


def validate_signup(data: dict[str, Any]) -> dict[str, str]:
    """
    Validate a sign-up payload.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        pydantic.ValidationError (a ValueError subclass) for missing/invalid fields.
    """
    try:
        payload = _SignupPayload.model_validate(data)
    except ValidationError:
        # Callers expect a ValueError-compatible exception; ValidationError satisfies that.
        raise

    return {
        "username": payload.username,
        "email": payload.email,
        "phone": payload.phone,
    }
